fn sign(x: Vec<i8>) -> Vec<i8> {
    // Pre-allocate the output vector with the same length as the input
    let mut result = Vec::with_capacity(x.len());

    // Classify each element of the input by its sign
    for v in x {
        let s = if v < 0 {
            -1
        } else if v > 0 {
            1
        } else {
            0
        };
        result.push(s);
    }

    result
}

